+export const MOTIVO_MINIMO = 10;
+
+// RF-006: regla de auditoría de EMBA. Un motivo, sin espacios en los bordes, tiene al menos 10 caracteres.
+export function validarMotivo(motivo) {
+  const limpio = typeof motivo === "string" ? motivo.trim() : "";
+  if (limpio.length === 0) throw new Error("El motivo es obligatorio");
+  if (limpio.length < MOTIVO_MINIMO) throw new Error(`El motivo necesita al menos ${MOTIVO_MINIMO} caracteres`);
+  return limpio;
+}
+
+// RF-005, ADR-002: devuelve una factura nueva "anulada"; la original no cambia.
+export function anularFactura(factura, motivo) {
+  if (!factura || factura.estado !== "emitida") throw new Error("Solo se anula una factura emitida");
+  return Object.freeze({ ...factura, estado: "anulada", motivo: validarMotivo(motivo) });
+}
